<div class="form-card"><h1 class="h3 mb-3"><?=isset($student)?'تعديل بيانات الطالب':'إضافة طالب جديد'?></h1><div id="ajax-errors" class="alert alert-danger d-none"></div><?php if(!empty($errors)): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $err): ?><li><?=e($err)?></li><?php endforeach; ?></ul></div><?php endif; ?><form method="post" enctype="multipart/form-data" id="student-form" novalidate><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach(['name'=>'اسم الطالب','email'=>'البريد الإلكتروني','phone'=>'رقم الهاتف','address'=>'العنوان'] as $key=>$label): ?><div class="mb-3"><label class="form-label" for="<?=$key?>"><?=$label?></label><?php if($key==='address'): ?><textarea class="form-control" id="address" name="address" rows="3" required><?=e($v['address'])?></textarea><?php else: ?><input class="form-control" id="<?=$key?>" name="<?=$key?>" <?= $key==='email'?'type="email"':'type="text"' ?> value="<?=e($v[$key])?>" required <?= $key==='name'?'maxlength="100"':($key==='email'?'maxlength="100"':($key==='phone'?'maxlength="15"':'')) ?>><?php endif; ?><div class="invalid-feedback">يرجى إدخال <?=e($label)?> بصورة صحيحة.</div></div><?php endforeach; ?><div class="mb-3"><label class="form-label">الصورة الشخصية (اختياري، حتى 2MB)</label><input type="file" class="form-control" name="profile_picture" accept="image/jpeg,image/png,image/gif,image/webp"><div class="form-text">الصيغ المدعومة: JPG, PNG, GIF, WEBP.</div><?php if(!empty($student['profile_picture'])): ?><img class="avatar mt-2" src="<?=BASE_URL?>/uploads/<?=e($student['profile_picture'])?>" alt="صورة الطالب الحالية"><?php endif; ?></div><button class="btn btn-primary" type="submit">حفظ البيانات</button> <a class="btn btn-outline-secondary" href="<?=BASE_URL?>/students/index.php">إلغاء</a></form></div>